def weighted_rrf(lists_with_weights, k=60):
    scores = {}
    for lst, w in lists_with_weights:
        for rank, d in enumerate(lst, start=1):
            scores[d] = scores.get(d, 0.0) + w / (k + rank)
    return sorted(scores, key=scores.get, reverse=True)

