from typing import List, Set


def recall_at_k(retrieved: List[List[str]], relevant: List[Set[str]], k: int) -> float:
    if len(retrieved) != len(relevant):
        raise ValueError("retrieved and relevant must have the same length")
    if k <= 0:
        raise ValueError("k must be positive")
    if not retrieved:
        return 0.0

    total = 0.0
    for got, rel in zip(retrieved, relevant):
        if not rel:
            continue
        top_k = set(got[:k])
        hits = len(top_k & rel)
        total += hits / len(rel)
    return total / len(retrieved)

