from typing import List, Set


def mean_reciprocal_rank(retrieved: List[List[str]], relevant: List[Set[str]]) -> float:
    if len(retrieved) != len(relevant):
        raise ValueError("retrieved and relevant must have the same length")
    if not retrieved:
        return 0.0

    total = 0.0
    for got, rel in zip(retrieved, relevant):
        rr = 0.0
        for rank, doc_id in enumerate(got, start=1):
            if doc_id in rel:
                rr = 1.0 / rank
                break
        total += rr
    return total / len(retrieved)

