def build_messages(question, chunks):
    ctx = "\n\n".join(f"[{i}] {c['text']}"
                       for i, c in enumerate(chunks, 1))
    return [
        {"role": "system",
         "content": "Answer only from the sources; cite [n]; "
                    "say you don't know if absent."},
        {"role": "user",
         "content": f"Sources:\n{ctx}\n\nQuestion: {question}"},
    ]
